package com.autoops.ai.tool.machine;import com.autoops.ai.tool.AITool;import com.autoops.machine.repository.MachineRepository;import org.springframework.stereotype.Component;import java.util.*;@Component public class ListMachinesTool implements AITool{private final MachineRepository repo;public ListMachinesTool(MachineRepository r){repo=r;}public String name(){return "list_machines";}public ToolRisk risk(){return ToolRisk.READ;}public Map<String,Object> schema(){return Map.of("type","object","properties",Map.of());}public Object execute(Map<String,Object>a,Long user){return repo.findByDeletedAtIsNull();}}
